def txt = { v -> (v == null) ? '' : String.valueOf(v).trim() }
def asLong = { v -> (v == null || String.valueOf(v).trim().isEmpty()) ? 0L : Long.valueOf(String.valueOf(v)) }
def md5hex = { String s -> java.security.MessageDigest.getInstance('MD5').digest(s.getBytes('UTF-8')).encodeHex().toString() }
def mint = { String seed -> 'e_' + md5hex(seed).substring(0, 24) }
final long DAY = 86400000L
// Ten management layers above a rep is bad data, not a tall company. Constant on purpose:
// a configurable cap only ever gets raised to get past data someone should have fixed.
final int MAX_DEPTH = 10

boolean isDry = (txt(dryRun) == 'true')

// ---- resolve positions by id, code or name -------------------------------
def posById = [:], posByCode = [:], posByName = [:]
(positions ?: []).each { r ->
    def p = r.properties ?: [:]
    posById[txt(r.id)] = r
    if (txt(p.positionCode) != '') posByCode[txt(p.positionCode).toLowerCase()] = r
    if (txt(p.name) != '') posByName[txt(p.name).toLowerCase()] = r
}
def findPos = { String ref ->
    if (ref == '') return null
    return posById[ref] ?: posByCode[ref.toLowerCase()] ?: posByName[ref.toLowerCase()]
}
def codeOf = { String id -> def r = posById[id]; return (r == null) ? '' : txt((r.properties ?: [:]).positionCode) }

// ---- every stored line, by position --------------------------------------
def linesByPos = [:]
(hierRows ?: []).each { r ->
    def p = r.properties ?: [:]
    String pid = txt(p.positionId)
    if (pid == '') return
    if (linesByPos[pid] == null) linesByPos[pid] = []
    linesByPos[pid] << [id: txt(r.id), parentId: txt(p.parentPositionId),
                        start: asLong(p.effectiveStart), end: asLong(p.effectiveEnd),
                        name: txt(p.name)]
}

def parseDay = { String s ->
    if (!(s ==~ /^\d{4}-\d{2}-\d{2}$/)) return -1L
    try { return java.time.LocalDate.parse(s).atStartOfDay(java.time.ZoneOffset.UTC).toInstant().toEpochMilli() }
    catch (Exception e) { return -1L }
}
def isoOf = { long ms -> java.time.Instant.ofEpochMilli(ms).atZone(java.time.ZoneOffset.UTC).toLocalDate().toString() }

// ---- pass 1: validate each row on its own --------------------------------
// A CSV written for Excel carries a BOM, and the reader hands the first header back
// mangled - 'position_id' arrives as '__position_id_'. Normalising every key means the
// template stays Excel-safe without the automation caring how the header was spelled.
def cell = { row, String want ->
    if (row == null) return ''
    def hit = row.find { k, v -> String.valueOf(k).toLowerCase().replaceAll(/[^a-z_]/, '').replaceAll(/^_+|_+$/, '') == want }
    return (hit == null) ? '' : txt(hit.value)
}

def out = []      // one entry per file row, in file order
def seen = [:]    // position ref -> the line that already claimed it
int line = 1
(rows ?: []).each { raw ->
    line += 1
    String posRef = cell(raw, 'position_id')
    String parRef = cell(raw, 'parent_position_id')
    String when = cell(raw, 'effective_from')
    def problems = []

    if (posRef == '') problems << 'position_id is required.'
    if (when == '') problems << 'effective_from is required.'
    long ms = (when == '') ? -1L : parseDay(when)
    if (when != '' && ms < 0) problems << ('effective_from "' + when + '" is not a date in YYYY-MM-DD form.')

    def posRec = findPos(posRef)
    if (posRef != '' && posRec == null) problems << ('No position "' + posRef + '".')
    def parRec = (parRef == '') ? null : findPos(parRef)
    if (parRef != '' && parRec == null) problems << ('No parent position "' + parRef + '".')

    String posId = (posRec == null) ? '' : txt(posRec.id)
    String parId = (parRec == null) ? '' : txt(parRec.id)
    if (posId != '' && posId == parId) problems << 'A position cannot report to itself.'

    // One change per position per file. Two rows for one seat cannot both be right, and
    // picking a winner would silently do something nobody asked for.
    if (posRef != '' && seen[posId] != null) problems << ('This position is already changed on line ' + seen[posId] + '.')
    else if (posId != '') seen[posId] = line

    String outcome = 'changed'
    def mine = (posId == '') ? [] : (linesByPos[posId] ?: [])
    String newId = (posId == '' || ms < 0) ? '' : mint('PositionHierarchy#' + posId + '#' + ms)

    if (problems.isEmpty()) {
        def exact = mine.find { it.start == ms && it.id != newId }
        def closedCovering = mine.find { it.end > 0L && it.start <= ms && it.end >= ms }
        def later = mine.find { it.start > ms }
        def current = mine.find { it.start <= ms && (it.end == 0L || it.end >= ms) }

        if (closedCovering != null) {
            problems << (when + ' falls inside closed history (' + isoOf(closedCovering.start) + ' to ' + isoOf(closedCovering.end) + '). Retro changes are manual.')
        } else if (parRef != '' && current != null && current.parentId == parId) {
            // Already reports to this parent, so there is nothing to do and nothing to refuse.
            // This has to be tested BEFORE the exact-date rule: the template is pre-filled
            // with each line's own start date, and those stored rows were not created by this
            // automation, so their ids are not minted ones. Testing the date first rejected an
            // unchanged re-upload - the one case that must always be a no-op.
            outcome = 'unchanged'
        } else if (exact != null) {
            problems << ('A line for this position already starts on ' + when + '.')
        } else if (later != null) {
            problems << (when + " is before this position's line of " + isoOf(later.start) + '. Backdating is manual.')
        } else if (parRef == '') {
            outcome = (current == null) ? 'unchanged' : 'closeOnly'
        }
    }

    out << [line: line, positionId: posRef, posId: posId, parId: parId, parRef: parRef,
            rawWhen: when, start: ms, newId: newId,
            outcome: problems.isEmpty() ? outcome : 'error', reason: problems.join(' ')]
}

// ---- pass 2: the cycle check, on the graph the file WOULD produce ---------
// Iterated to a fixpoint. Dropping a row does NOT remove an edge - it reverts that
// position to its STORED parent, and a restored edge can close a fresh loop with the rows
// that survived. One pass would miss that and commit a cyclic reporting line.
def parentNow = [:]
linesByPos.each { pid, ls ->
    def open = ls.find { it.end == 0L }
    parentNow[pid] = (open == null) ? '' : open.parentId
}
boolean settled = false
int guard = 0
while (!settled && guard < 25) {
    guard += 1
    def graph = [:]
    parentNow.each { k, v -> graph[k] = v }
    out.each { r ->
        if (r.outcome == 'error' || r.outcome == 'unchanged') return
        graph[r.posId] = (r.outcome == 'closeOnly') ? '' : r.parId
    }
    def offenders = [] as Set
    graph.keySet().each { startNode ->
        def visited = [] as LinkedHashSet
        def path = []
        String cur = startNode
        int depth = 0
        while (cur != null && cur != '') {
            if (!visited.add(cur)) { path.each { offenders << it }; break }
            path << cur
            depth += 1
            if (depth > MAX_DEPTH) { path.each { offenders << it }; break }
            cur = graph[cur]
        }
    }
    settled = true
    if (!offenders.isEmpty()) {
        out.each { r ->
            if (r.outcome == 'error' || r.outcome == 'unchanged') return
            if (offenders.contains(r.posId)) {
                r.outcome = 'error'
                r.reason = 'These reporting lines would form a loop, so this row was not applied.'
                settled = false
            }
        }
    }
}

// ---- pass 3: plan the write ----------------------------------------------
def updates = []
def usedIds = [] as Set
out.each { r ->
    if (r.outcome != 'changed' && r.outcome != 'closeOnly') return
    def mine = linesByPos[r.posId] ?: []
    def current = mine.find { it.start <= r.start && (it.end == 0L || it.end >= r.start) }
    def set = { String f, v -> [fieldName: 'properties.' + f, actionType: 'SET', setValue: v] }

    if (r.outcome == 'closeOnly') {
        if (current != null) updates << [id: current.id, updateFields: [set('effectiveEnd', r.start - DAY)]]
        return
    }
    // Two rows for one position on one date would mint the same id and appear twice in a
    // single batch, which the upsert cannot resolve. The duplicate check above makes this
    // unreachable; it stays because being wrong here writes the wrong parent.
    if (!usedIds.add(r.newId)) {
        r.outcome = 'error'
        r.reason = 'Two rows in this file would write the same record.'
        return
    }
    if (current != null && current.id != r.newId) {
        updates << [id: current.id, updateFields: [set('effectiveEnd', r.start - DAY)]]
    }
    def f = [set('positionId', r.posId), set('parentPositionId', r.parId), set('effectiveStart', r.start),
             set('name', codeOf(r.posId) + ' -> ' + codeOf(r.parId) + ' from ' + isoOf(r.start))]
    // Open is NULL, never 0. Zero is a real instant (1970), which reads as long-closed and
    // drops the position out of every as-of query.
    f << set('effectiveEnd', null)
    updates << [id: r.newId, updateFields: f]
}

// A column missing from the header shows up as that value being blank on EVERY row, which
// reads as a hundred identical row errors instead of the one thing actually wrong. Say it once.
if (!out.isEmpty()) {
    def missing = []
    if (out.every { txt(it.positionId) == '' }) missing << 'position_id'
    if (out.every { it.start < 0 }) missing << 'effective_from'
    if (!missing.isEmpty()) {
        String msg = 'The file is missing the ' + missing.join(' and ') + ' column' + (missing.size() == 1 ? '' : 's') + '.'
        out.each { it.outcome = 'error'; it.reason = msg }
    }
}

int errors = out.count { it.outcome == 'error' }
int changed = out.count { it.outcome == 'changed' || it.outcome == 'closeOnly' }
String status
if (out.isEmpty()) status = 'INVALID_INPUT'
else if (errors == out.size()) status = 'REFUSED'
else if (errors > 0) status = 'PARTIAL'
else status = 'APPLIED'

if (isDry) updates = []

// Every row comes back, not just the failures: the error file is the user's own file with
// one column added, so it can be corrected and re-uploaded whole rather than reassembled.
def reported = out.collect { [line: it.line,
                              position_id: it.positionId,
                              parent_position_id: it.parRef,
                              effective_from: it.rawWhen,
                              outcome: (it.outcome == 'closeOnly') ? 'changed' : it.outcome,
                              error: it.reason] }

return [status: status, updates: updates, rows: reported,
        applied: changed, written: updates.size(),
        message: isDry ? 'Preview only - nothing was written.' : '']
